const button=(key,cmd,opts={})=>`<button type="button" class="${opts.class||''}" data-cmd="${e(cmd)}" ${opts.id?`data-id="${e(opts.id)}"`:''} ${opts.disabled?'disabled':''} ${opts.title?`title="${e(opts.title)}"`:''}>${opts.icon?icon(opts.icon):''}${e(t(key))}</button>`;
const badge=(value)=>`<span class="badge ${e(value)}">${e(t(value))}</span>`;
const score=(value)=>`<span class="score"><span class="score-track"><i style="width:${Math.min(100,Math.max(0,Number(value)||0))}%"></i></span><b>${Math.round(value||0)}</b></span>`;
const empty=()=>`<div class="empty">${icon('search')}<strong>${e(t('noResults'))}</strong>${e(t('noResultsHint'))}</div>`;
const panel=(title,body,extra='',sub='')=>`<section class="panel"><div class="panel-head"><div><h2>${e(t(title))}</h2>${sub?`<p class="muted">${e(sub)}</p>`:''}</div>${extra}</div>${body}</section>`;
const raw=(obj)=>`<pre class="raw-json">${e(JSON.stringify(obj,null,2))}</pre>`;
const localeSelect=()=>`<select aria-label="${e(t('locale'))}" data-locale><option value="uz" ${locale==='uz'?'selected':''}>O‘zbek</option><option value="ru" ${locale==='ru'?'selected':''}>Русский</option><option value="en" ${locale==='en'?'selected':''}>English</option></select>`;
const reasonField=()=>`<div class="field"><label for="reason">${e(t('reason'))}</label><textarea id="reason" name="reason" minlength="8" maxlength="600" required placeholder="${e(t('reasonPlaceholder'))}"></textarea></div>`;
const optionList=(items,value,allLabel='all')=>`<option value="">${e(t(allLabel))}</option>${items.map(x=>`<option value="${e(x)}" ${value===x?'selected':''}>${e(t(x))}</option>`).join('')}`;

function toast(text,error=false){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.innerHTML=`${icon(error?'alert':'check')}<span>${e(text)}</span><button aria-label="${e(t('close'))}">${icon('close')}</button>`;el.querySelector('button').onclick=()=>el.remove();document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),error?12000:6000);}
function errorText(err){const code=typeof err==='string'?err:err.message;return errors[code]?.[{uz:0,ru:1,en:2}[locale]]||t(errorKeys[code]||'requestFailed')+(code?` · ${code}`:'');}
async function api(path,body,method){let result;try{result=await fetch(path,{method:method||(body===undefined?'GET':'POST'),credentials:'same-origin',headers:{...(body!==undefined?{'Content-Type':'application/json'}:{}),...(auth?{'X-CSRF-Token':auth.csrf_token}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});}catch{throw Error('NETWORK_UNAVAILABLE');}const content=await result.json();if(!result.ok){if(result.status===401&&auth){auth=null;renderLogin();}throw Error(typeof content.detail==='string'?content.detail:'INVALID_INPUT');}return content;}
const canAutoRefresh=()=>auth&&!document.hidden&&!dialog.open&&!document.querySelector('.sidebar.open')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);
async function refresh(render=true,background=false){if(fetching)return;fetching=true;try{state=await api('/api/state');if(render&&(!background||canAutoRefresh()))renderApp();}catch(err){toast(errorText(err),true);}finally{fetching=false;}}
async function mutate(path,body={}){const result=await api(path,body);await refresh();toast(t('mutationSuccess'));return result;}
function navigate(next){location.hash=next;}

function renderLogin(error=''){
 document.documentElement.lang=locale;document.querySelector('.skip-link').textContent=t('skip');
 app.innerHTML=`<div class="login-shell"><section class="login-story"><div class="brand"><div class="brand-mark">${icon('shield')}</div><div><strong>AI-SOC</strong><small>SENTINEL / 01</small></div></div><h1>${e(t('loginStory'))}<br><span>${e(t('loginStoryAccent'))}</span></h1><p>${e(t('loginStoryText'))}</p><div class="login-signals">${['loginSignal1','loginSignal2','loginSignal3'].map((x,i)=>`<div><strong>0${i+1}</strong><small>${e(t(x))}</small></div>`).join('')}</div></section><main class="login-card-wrap" id="main"><div class="login-card"><div class="locale-wrap">${localeSelect()}</div><p class="eyebrow">SENTINEL CONSOLE</p><h2>${e(t('loginTitle'))}</h2><p>${e(t('loginSubtitle'))}</p>${error?`<div class="error-box" role="alert">${e(error)}</div>`:''}<form id="login-form"><div class="field"><label for="username">${e(t('username'))}</label><input id="username" name="username" autocomplete="username" required maxlength="80"></div><div class="field"><label for="password">${e(t('password'))}</label><input id="password" name="password" type="password" autocomplete="current-password" required maxlength="256"></div><button type="submit" class="primary">${e(t('signIn'))}${icon('arrow')}</button></form><div class="divider">${e(t('demoAccess'))}</div><div class="role-grid">${['analyst','ml_engineer','approver','auditor','admin'].map(role=>button(role,'demo-login',{id:role,icon:role==='ml_engineer'?'brain':'users'})).join('')}</div><p class="login-note">${e(t('loginNote'))}</p></div></main></div>`;
}

const navItems=[['overview','grid'],['lab','play'],['incidents','alert'],['events','activity'],['responses','shield'],['learning','brain'],['dataset','database'],['audit','audit'],['sources','server'],['judge','play'],['settings','settings']];
function renderApp(){
 if(!auth||!state)return;route=location.hash.slice(1)||'overview';if(!navItems.some(x=>x[0]===route))route='overview';
 document.documentElement.lang=locale;document.title=`${t(route)} · AI-SOC`;document.querySelector('.skip-link').textContent=t('skip');
 app.innerHTML=`<div class="layout"><div class="overlay" data-cmd="menu-close"></div><aside class="sidebar"><a class="brand" href="#overview"><div class="brand-mark">${icon('shield')}</div><div><strong>AI-SOC</strong><small>SENTINEL / 01</small></div></a><div class="workspace"><div class="workspace-logo">${icon('server')}</div><div><strong>Meridian ${state.meta.synthetic?'Sandbox':'Pilot'}</strong><small>${e(t('workspaceSub'))}</small></div></div><p class="nav-caption">${e(t('operations'))}</p><nav class="nav" aria-label="${e(t('menu'))}">${navItems.map(([key,ico],idx)=>`${idx===4?`<p class="nav-caption section-gap">${e(t('intelligence'))}</p>`:''}<a href="#${key}" class="${route===key?'active':''}" ${route===key?'aria-current="page"':''}>${icon(ico)}<span>${e(t(key))}</span>${key==='incidents'?`<span class="nav-count">${state.overview.incidents_open}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="engine-status"><div><span class="status-dot"></span>${e(t('engineReady'))}</div><small class="muted">${e(state.overview.model_version)} · LOCAL</small></div><div class="profile"><div class="avatar">${e(auth.user.role.slice(0,2).toUpperCase())}</div><div class="identity"><strong>${e(t(auth.user.role))}</strong><small>${e(auth.user.username)}</small></div><button class="icon-button ghost" data-cmd="logout" aria-label="${e(t('logout'))}" title="${e(t('logout'))}">${icon('logout')}</button></div></div></aside><div class="main-shell"><header class="topbar"><button class="icon-button mobile-menu" data-cmd="menu" aria-label="${e(t('menu'))}">${icon('menu')}</button><form class="global-search" id="global-search">${icon('search')}<input name="q" aria-label="${e(t('searchLabel'))}" placeholder="${e(t('search'))}" value="${route==='incidents'?e(pageFilter.q):''}"><kbd>/</kbd></form><div class="topbar-right"><span class="demo-pill">${e(t(state.meta.synthetic?'syntheticDemo':'pilot'))}</span><span class="clock">${date(state.meta.now,true)} UTC</span>${localeSelect()}<button class="icon-button refresh-button" data-cmd="refresh" aria-label="${e(t('refresh'))}" title="${e(t('refresh'))}">${icon('refresh')}</button></div></header><main class="content" id="main" tabindex="-1"><div class="page-heading"><div><div class="eyebrow">${e(t('workspace'))}</div><h1>${e(t(route))}</h1><p>${e(t(route+'Description'))}</p></div><div class="heading-actions">${headerActions()}</div></div>${state.meta.synthetic?`<div class="safety-banner">${icon('info')}<div><strong>${e(t('demoBannerTitle'))}</strong> ${e(t(route==='lab'?'labBoundary':'demoBanner'))}</div></div>`:''}<div id="page">${pages[route]()}</div><footer class="footer"><span>${icon('shield')}${e(t('footerLeft'))}</span><span>${e(t('lastRefresh'))}: ${date(state.meta.now)} UTC · v${e(state.meta.version)}</span></footer></main></div></div>`;
 if(route==='events')loadEvents();if(route==='dataset')loadDataset();if(route==='lab')loadLab();
}
function headerActions(){if(route==='lab')return '';if(route==='learning')return button('train','train',{class:'primary',icon:'brain',disabled:!canTrain()});if(route==='dataset')return button('exportDataset','export-dataset',{icon:'download',disabled:!canExport()});if(route==='audit'||route==='judge')return button('exportEvidence','export-evidence',{icon:'download',disabled:!canExport()});return state.meta.synthetic?button('replay','replay',{class:'primary',icon:'play',disabled:!allowed('analyst','admin')}):'';}
function stats(items){return `<div class="stats">${items.map(([title,value,sub,ico])=>`<div class="stat"><div class="stat-top">${e(t(title))}${icon(ico||'activity')}</div><div class="stat-value">${e(typeof value==='number'?n(value):value)}</div><div class="stat-foot">${e(t(sub))}</div></div>`).join('')}</div>`;}
function chart(){const values=state.overview.alert_trend,W=680,H=188,left=32,top=13,bottom=160;const max=Math.max(1,...values.map(x=>x.events));const xy=(v,i)=>[left+i*(W-left-12)/Math.max(values.length-1,1),bottom-v/max*(bottom-top)];const path=(key)=>values.map((x,i)=>`${i?'L':'M'}${xy(x[key],i).join(',')}`).join(' ');return `<div class="chart-wrap"><svg class="trend-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${e(t('threatActivity'))}">${[0,.5,1].map(x=>`<path class="grid-line" d="M${left},${bottom-x*(bottom-top)}H${W}"/><text x="1" y="${bottom-x*(bottom-top)+3}">${Math.round(x*max)}</text>`).join('')}<path d="${path('events')} L${W-12},${bottom} L${left},${bottom}Z" fill="#438de914"/><path class="event-line" d="${path('events')}"/><path class="alert-line" d="${path('alerts')}"/>${values.filter((_,i)=>i%2===0).map((x,j)=>`<text x="${xy(0,j*2)[0]}" y="181" text-anchor="middle">${date(x.hour,true)}</text>`).join('')}</svg></div>`;}
function donut(){const levels=['critical','high','medium','low'],colors=['#ff8493','#f2c271','#83b4ff','#69e6c5'];const totals=levels.map(s=>state.incidents.filter(i=>i.severity===s&&i.status!=='closed').length),sum=totals.reduce((a,b)=>a+b,0);let start=0;return `<div class="panel-body"><div class="threat-distribution"><div class="donut"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="42" fill="none" stroke="#26364b" stroke-width="9"/>${totals.map((count,i)=>{const length=count/Math.max(sum,1)*263.89;const svg=`<circle cx="50" cy="50" r="42" fill="none" stroke="${colors[i]}" stroke-width="9" stroke-dasharray="${Math.max(0,length-3)} ${263.89-Math.max(0,length-3)}" stroke-dashoffset="${-start}"/>`;start+=length;return svg;}).join('')}</svg><div class="donut-center"><strong>${sum}</strong><small>${e(t('activeQueue'))}</small></div></div><div class="distribution-legend">${levels.map((s,i)=>`<div><span class="dot ${s}"></span>${e(t(s))}<b>${totals[i]}</b></div>`).join('')}</div></div><p class="summary-note">${e(t('riskNote'))}</p></div>`;}
function incidentTable(rows){if(!rows.length)return empty();return `<div class="table-wrap"><table><thead><tr>${['incident','severity','asset','riskScore','status','time'].map(k=>`<th scope="col">${e(t(k))}</th>`).join('')}</tr></thead><tbody>${rows.map(i=>`<tr><td><button class="link-button" data-cmd="incident" data-id="${e(i.id)}">${e(t(i.title_code))}</button><span class="cell-sub mono">${e(i.id)}</span></td><td>${badge(i.severity)}</td><td><span class="primary-cell mono">${e(i.asset_id)}</span><span class="cell-sub">${e(i.owner||t('unassigned'))}</span></td><td>${score(i.score)}</td><td>${badge(i.status)}</td><td>${date(i.updated_at)}<span class="cell-sub">UTC</span></td></tr>`).join('')}</tbody></table></div>`;}
function activityList(rows){return `<div class="panel-body">${rows.slice(0,5).map(a=>`<div class="activity-row"><span class="activity-dot"></span><div><strong>${e(a.action)}</strong><small>${e(a.actor)} · ${e(a.target)}</small></div><time>${date(a.time,true)}</time></div>`).join('')||empty()}</div>`;}
function overview(){const o=state.overview;return stats([['totalEvents',o.events_total,'fromTelemetry','activity'],['openIncidents',o.incidents_open,'needsAttention','alert'],['criticalIncidents',o.critical_incidents,'priorityNow','shield'],['reviewQueue',o.review_queue,'independentReview','users']])+`<div class="grid two">${panel('threatActivity',chart(),`<div class="legend"><span><i class="blue"></i>${e(t('events'))}</span><span><i></i>${e(t('alerts'))}</span></div>`,t('recentWindow'))}${panel('severityMix',donut())}</div><div class="grid two section-gap">${panel('priorityIncidents',incidentTable(state.incidents.filter(i=>i.status!=='closed').slice(0,6)),button('viewAll','go-incidents',{class:'small ghost'}))}${panel('learningSnapshot',`<div class="panel-body">${metricRows([['activeModel',o.model_version],['reviewedLabels',n(state.learning.confirmed_labels)],['trainingData',n(state.learning.dataset_count)],['drift',t(state.learning.drift.status)]])}<div class="callout section-gap"><strong>${e(t('manualLearning'))}</strong><p>${e(t('automationNone'))}</p></div><div class="button-row section-gap">${button('learning','go-learning',{class:'small'})}</div></div>`)}</div><div class="grid equal section-gap">${panel('connectedSources',connectorList())}${panel('recentAudit',activityList(state.audit),button('viewAll','go-audit',{class:'small ghost'}))}</div>`;}
function metricRows(rows){return rows.map(([key,value])=>`<div class="metric-row"><span>${e(t(key))}</span><strong>${e(value)}</strong></div>`).join('');}
function filters(kind){return `<div class="toolbar"><div class="filter-group"><input data-filter="q" type="search" aria-label="${e(t('search'))}" placeholder="${e(t('filterSearch'))}" value="${e(pageFilter.q)}"></div><div class="filter-group"><select data-filter="severity" aria-label="${e(t('severity'))}">${optionList(['critical','high','medium','low'],pageFilter.severity,'allSeverity')}</select>${kind==='incidents'?`<select data-filter="status" aria-label="${e(t('status'))}">${optionList(['open','investigating','contained','closed'],pageFilter.status,'allStatus')}</select>`:`<select data-filter="source" aria-label="${e(t('source'))}">${optionList(['identity','endpoint','network','core_banking'],pageFilter.source,'allSources')}</select>`}</div></div>`;}
function filteredIncidents(){return state.incidents.filter(i=>(!pageFilter.severity||i.severity===pageFilter.severity)&&(!pageFilter.status||i.status===pageFilter.status)&&(!pageFilter.q||[i.id,i.asset_id,i.entity_id,t(i.title_code),i.owner,...(i.ip_addresses||[])].join(' ').toLowerCase().includes(pageFilter.q.toLowerCase())));}
function incidents(){return panel('incidents',filters('incidents')+`<div id="incident-results">${incidentTable(filteredIncidents())}</div><div class="panel-footer">${e(t('riskNote'))}</div>`);}
function events(){return panel('events',filters('events')+`<div id="event-results"><div class="empty">${t('loading')}</div></div>`);}
async function loadEvents(){
 const request=++eventRequestSeq, requestedPage=eventPage, target=document.querySelector('#event-results');
 const isCurrent=()=>request===eventRequestSeq&&requestedPage===eventPage&&route==='events'&&target===document.querySelector('#event-results');
 if(!target)return;
 try{
  const q=new URLSearchParams({...pageFilter,offset:requestedPage*50,limit:50}), result=await api('/api/events?'+q);
  if(!isCurrent())return;
  eventData=result;
  const start=result.items.length?requestedPage*50+1:0, end=result.items.length?Math.min(requestedPage*50+result.items.length,result.total):0;
  target.innerHTML=eventTable(result.items)+`<div class="panel-footer"><span>${n(start)}–${n(end)} / ${n(result.total)} ${e(t('records'))}</span><div class="button-row">${button('previous','event-prev',{class:'small',disabled:requestedPage===0})}${button('next','event-next',{class:'small',disabled:(requestedPage+1)*50>=result.total})}</div></div>`;
 }catch(err){if(isCurrent())toast(errorText(err),true);}
}
function eventTable(rows){if(!rows.length)return empty();return `<div class="table-wrap"><table><thead><tr>${['time','eventType','source','asset','sourceIp','riskScore','detail'].map(k=>`<th scope="col">${e(t(k))}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr><td>${date(x.event_time)}<span class="cell-sub">UTC</span></td><td>${e(t(x.event_type))}<span class="cell-sub mono">${e(x.id)}</span></td><td>${e(t(x.source))}</td><td class="mono">${e(x.asset_id)}</td><td class="mono">${e(x.src_ip)}</td><td>${score(x.score)}</td><td>${button('inspect','event',{id:x.id,class:'small ghost'})}</td></tr>`).join('')}</tbody></table></div>`;}
function learning(){const l=state.learning;return `<div class="callout"><strong>${e(t('manualLearning'))}</strong><p>${e(t('manualLearningText'))}</p></div><div class="steps section-gap">${['collect','review','evaluate','promote'].map((k,i)=>`<div class="step"><span class="step-number">0${i+1}</span><b>${e(t(k))}</b><small>${e(t(k+'Desc'))}</small></div>`).join('')}</div>${stats([['totalLabels',l.labels_total,'labelCountHint','users'],['trainingData',l.dataset_count,'trainingData','database'],['models',state.models.length,'manualLearning','brain'],['drift',t(l.drift.status),'dataShift','activity']])}<div class="grid two">${panel('models',state.models.map(modelCard).join(''))}<div class="stack">${panel('readiness',`<div class="panel-body">${metricRows([['trainingData',n(l.readiness.rows)],['positive',n(l.readiness.positive)],['negative',n(l.readiness.negative)],['syntheticDemo',n(l.readiness.synthetic_rows)]])}<p class="tiny muted section-gap">${e(t('minimumRows'))}</p><div class="button-row section-gap">${badge(l.readiness.ready_for_review?'ready':'blocked')}${button('dataset','go-dataset',{class:'small'})}</div></div>`)}${panel('drift',`<div class="panel-body"><p class="tiny muted">${e(t('dataShift'))} · PSI</p>${(l.drift.features||[]).slice(0,5).map(x=>`<div class="metric-row"><code>${e(x.feature)}</code><strong>${x.psi.toFixed(3)}</strong></div>`).join('')}<p class="tiny muted section-gap">${e(t('automationNone'))}</p></div>`)}${panel('manifest',`<div class="panel-body">${l.latest_manifest?manifestView(l.latest_manifest):`<p class="muted small-text">${e(t('noManifest'))}</p>`}</div>`)}</div></div><div class="section-gap">${panel('trainingRun',l.runs.length?`<div class="panel-body">${l.runs.map(r=>`<div class="metric-row"><span><code>${e(r.id)}</code><br>${e(r.actor)} · ${date(r.created_at)}</span>${badge(r.status)}</div>`).join('')}</div>`:empty())}</div>`;}
function modelCard(m){const c=m.metrics?.candidate,h=m.metrics?.operational_hybrid;return `<article class="model-card"><div class="model-header"><div><h3>${e(m.version)}</h3><p class="mono">${e(m.id)}</p></div>${badge(m.status)}</div>${m.data_review_required?`<div class="callout warning section-gap">${e(errorText('TRAINING_LABELS_CHANGED'))}</div>`:''}${c?`<div class="model-metrics">${['precision','recall','fpr','pr_auc'].map(k=>`<div><small>${e(t(k))}</small><strong>${pct(c[k])}</strong></div>`).join('')}</div><p class="tiny muted section-gap">${e(t('metricsSynthetic'))} · ${e(m.metrics.selection?.model||'')}</p>`:`<p class="tiny muted section-gap">${e(t('riskNote'))}</p>`}${h?`<div class="callout warning section-gap"><strong>${e(t('hybrid'))}</strong><div class="model-metrics">${['precision','recall','fpr'].map(k=>`<div><small>${e(t(k))}</small><strong>${pct(h[k])}</strong></div>`).join('')}</div><p class="tiny section-gap">${e(t('hybridNote'))}</p></div>`:''}${m.gates?.length?`<div class="gates">${m.gates.map(g=>`<span class="gate ${g.passed?'pass':'fail'}" title="${e(JSON.stringify({observed:g.observed,required:g.required}))}">${icon(g.passed?'check':'alert')}${e(t(g.name))}</span>`).join('')}</div>`:''}<details><summary>${e(t('details'))} · ${e(t('artifactHash'))}</summary>${raw({artifact_hash:m.artifact_hash,metrics:m.metrics,gates:m.gates,production_eligible:m.production_eligible,evaluation_status:m.evaluation_status})}</details><div class="model-actions"><small>${e(t('trainedBy'))}: ${e(m.trained_by)}<br>${e(t('approvedBy'))}: ${e(m.approved_by||'—')}</small><div class="button-row">${m.status==='challenger'?button('promote','promote',{id:m.id,class:'small primary',disabled:!canReview()||!m.eligible||m.trained_by===auth.user.username}):''}${m.status==='retired'?button('rollback','model-rollback',{id:m.id,class:'small',disabled:!allowed('admin')}):''}</div></div></article>`;}
function manifestView(m){const cohorts=m.cohorts||{};return `<p class="tiny muted">${e(t('splitHint'))}</p><div class="split-grid">${Object.entries(cohorts).map(([key,v])=>`<div class="split-card"><small>${e(t(key==='train'?'trainSplit':key))}</small><b>${n(v.count)}</b><span>${e(t('positive'))}: ${n(v.positives)}</span></div>`).join('')}</div><details><summary>${e(t('manifest'))}</summary>${raw(m)}</details>`;}
function dataset(){return `<div class="callout"><strong>${e(t('privacy'))}</strong><p>${e(t('privacyText'))}</p></div><div class="grid equal section-gap">${panel('labelsQueue',state.labels.length?state.labels.map(labelCard).join(''):`<div class="empty"><strong>${e(t('noLabels'))}</strong>${e(t('labelHint'))}${button('incidents','go-incidents',{class:'small'})}</div>`)}${panel('readiness',`<div class="panel-body">${metricRows([['trainingData',n(state.learning.dataset_count)],['reviewedLabels',n(state.learning.confirmed_labels)],['positive',n(state.learning.readiness.positive)],['negative',n(state.learning.readiness.negative)]])}<p class="tiny muted section-gap">${e(t('minimumRows'))}</p><p class="tiny muted section-gap">${e(t('manualLearningText'))}</p><details><summary>SHA-256</summary><code>${e(state.learning.dataset_hash)}</code></details></div>`)}</div><div class="section-gap">${panel('scanRows',`<div id="dataset-results"><div class="empty">${e(t('loading'))}</div></div>`)}</div>`;}
function labelCard(l){const approve=canReview()&&l.created_by!==auth.user.username&&l.label!=='uncertain';return `<article class="review-card"><div class="model-header"><h3>${l.incident_id?`<button class="link-button" data-cmd="incident" data-id="${e(l.incident_id)}">${e(l.incident_id)}</button>`:`<code>${e(l.event_id)}</code>`}</h3>${badge(l.status)}</div><div class="meta-line">${badge(l.label)} · ${e(t('submittedBy'))}: ${e(l.created_by)} · ${date(l.created_at)}</div><p class="review-reason">${e(l.reason)}</p><div class="button-row">${l.status==='pending'?button('approve','label-approve',{id:l.id,class:'small primary',disabled:!approve})+button('reject','label-reject',{id:l.id,class:'small',disabled:!canReview()||l.created_by===auth.user.username}):`<span class="tiny muted">${e(t('reviewedBy'))}: ${e(l.reviewed_by||'—')}</span>`}</div></article>`;}
async function loadDataset(){
 const request=++datasetRequestSeq, requestedPage=datasetPage, target=document.querySelector('#dataset-results'), datasetHash=state.learning.dataset_hash;
 const isCurrent=()=>request===datasetRequestSeq&&requestedPage===datasetPage&&route==='dataset'&&target===document.querySelector('#dataset-results');
 if(!target)return;
 try{
  const result=await api(`/api/dataset?offset=${requestedPage*30}&limit=30`);
  if(!isCurrent())return;
  datasetData=result;
  const rows=result.items, start=rows.length?requestedPage*30+1:0, end=rows.length?Math.min(requestedPage*30+rows.length,result.total):0;
  target.innerHTML=(rows.length?`<div class="table-wrap"><table><thead><tr>${['eventId','label','provenance','time','features'].map(k=>`<th scope="col">${e(t(k))}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td class="mono">${e(r.event_id)}</td><td>${badge(r.label?'malicious':'benign')}</td><td>${badge(r.synthetic?'syntheticDemo':'confirmed')}<span class="cell-sub">${e(r.provenance)}</span></td><td>${date(r.label_available_at)} UTC</td><td>${button('inspect','dataset-row',{id:r.event_id,class:'small ghost'})}</td></tr>`).join('')}</tbody></table></div>`:empty())+`<div class="panel-footer"><span>${n(start)}–${n(end)} / ${n(result.total)} ${e(t('records'))} · SHA-256 ${e(datasetHash.slice(0,16))}</span><div class="button-row">${button('previous','dataset-prev',{class:'small',disabled:requestedPage===0})}${button('next','dataset-next',{class:'small',disabled:(requestedPage+1)*30>=result.total})}</div></div>`;
 }catch(err){if(isCurrent())target.innerHTML=`<div class="empty">${e(errorText(err))}</div>`;}
}
function responses(){return `<div class="callout warning"><strong>${e(t('actionSimulated'))}</strong><p>${e(t('planHint'))}</p></div><div class="section-gap">${panel('actionQueue',state.actions.length?state.actions.map(actionCard).join(''):`<div class="empty"><strong>${e(t('noActions'))}</strong>${e(t('noActionsHint'))}</div>`,badge(state.policies.kill_switch?'killOn':'killOff'))}</div>`;}
function actionCard(a){return `<article class="review-card"><div class="model-header"><div><h3>${e(t(a.kind))} · <code>${e(a.target)}</code></h3><p class="mono muted tiny">${e(a.id)}</p></div>${badge(a.status)}</div><p class="review-reason">${e(a.reason)}</p><div class="meta-line">${e(t('requestedBy'))}: ${e(a.requested_by)} · ${e(t('approvedBy'))}: ${e(a.approved_by||'—')}<br>${e(t('expires'))}: ${date(a.expires_at)} UTC · Policy ${e(a.policy_version)}</div><details><summary>${e(t('details'))}</summary>${raw(a)}</details><div class="button-row section-gap">${a.status==='awaiting_approval'?button('approve','action-approve',{id:a.id,class:'small primary',disabled:!canReview()||a.requested_by===auth.user.username}):''}${['awaiting_approval','approved'].includes(a.status)?button('reject','action-reject',{id:a.id,class:'small',disabled:!canReview()}):''}${a.status==='approved'?button('execute','action-execute',{id:a.id,class:'small primary',disabled:!canWrite()}):''}${a.status==='executed'?button('verify','action-verify',{id:a.id,class:'small primary',disabled:!canWrite()}):''}${['executed','verified'].includes(a.status)?button('rollback','action-rollback',{id:a.id,class:'small',disabled:!canReview()}):''}</div></article>`;}
function filteredAudit(){const value=auditFilter.toLowerCase();return state.audit.filter(a=>[a.actor,a.action,a.target,a.id].join(' ').toLowerCase().includes(value));}
function audit(){return panel('audit',`<div class="toolbar"><div class="filter-group"><input data-audit-filter type="search" aria-label="${e(t('auditSearch'))}" placeholder="${e(t('auditSearch'))}" value="${e(auditFilter)}"></div>${button('verifyChain','verify-chain',{icon:'shield',class:'small'})}</div><div class="panel-body"><p class="small-text muted">${e(t('auditWindow'))}</p></div><div id="audit-verification" class="panel-body"></div><div id="audit-results">${auditTable(filteredAudit())}</div><div class="panel-footer">${e(t('chainHint'))}</div>`);}
function auditTable(rows){return `<div class="table-wrap"><table><thead><tr>${['time','actor','action','target','recordHash','detail'].map(k=>`<th>${e(t(k))}</th>`).join('')}</tr></thead><tbody>${rows.map(a=>`<tr><td>${date(a.time)} UTC</td><td>${e(a.actor)}</td><td class="mono">${e(a.action)}</td><td class="mono">${e(a.target)}</td><td class="mono hash" title="${e(a.hash)}">${e(a.hash.slice(0,16))}…</td><td>${button('inspect','audit-row',{id:a.id,class:'small ghost'})}</td></tr>`).join('')}</tbody></table></div>`;}
function connectorList(){return `<div class="panel-body">${state.connectors.map(c=>`<div class="connector-row"><div class="connector-icon">${icon('server')}</div><div class="connector-text"><strong>${e(t(c.category))}</strong><small>${n(c.event_count)} ${e(t('events'))} · ${date(c.last_seen)} UTC</small></div>${badge(c.status)}</div>`).join('')}</div>`;}
function sources(){return `<div class="callout"><strong>${e(t('sourceBoundary'))}</strong><p>${e(t('sourceBoundaryText'))}</p><p>${e(t('sourceCoverage'))}</p></div><div class="grid two section-gap">${panel('assetInventory',`<div class="table-wrap"><table><thead><tr>${['asset','type','criticality'].map(k=>`<th>${e(t(k))}</th>`).join('')}</tr></thead><tbody>${state.assets.map(a=>`<tr><td><span class="mono">${e(a.id)}</span><span class="cell-sub">${e(a.name)}</span></td><td>${e(t(a.type))}</td><td>${badge(a.criticality)}</td></tr>`).join('')}</tbody></table></div>`)}${panel('connectors',connectorList())}</div>`;}
function judge(){return panel('judge',`${[1,2,3,4,5].map((i)=>`<div class="judge-step"><div class="judge-number">0${i}</div><div><h3>${e(t('judge'+i))}</h3><p>${e(t('judge'+i+'Text'))}</p><div class="button-row">${i===1?button('replay','replay',{class:'small primary',disabled:!allowed('analyst','admin')}):i===2?button('incidents','go-incidents',{class:'small'}):i===3?button('dataset','go-dataset',{class:'small'})+button('learning','go-learning',{class:'small'}):i===4?button('responses','go-responses',{class:'small'}):button('audit','go-audit',{class:'small'})+button('exportEvidence','export-evidence',{class:'small',disabled:!canExport()})}</div></div></div>`).join('')}<div class="panel-body"><div class="callout warning"><strong>${e(t('acceptance'))}</strong><p>${e(t('acceptanceText'))}</p><p>${e(t('manualLearningText'))}</p></div></div>`);}
function settings(){return `<div class="grid equal">${panel('environment',`<div class="panel-body">${metricRows([['tenant',state.meta.tenant],['mode',t(state.meta.synthetic?'demo':'pilot')],['version',state.meta.version],['currentRole',t(auth.user.role)],['timestamps','UTC'],['locale',{uz:'O‘zbek (lotin)',ru:'Русский',en:'English'}[locale]]])}<p class="tiny muted section-gap">${e(t('roleHint'))}</p></div>`)}${panel('safetyControls',`<div class="panel-body"><div class="security-line"><div><h3>${e(t('approvalRequired'))}</h3><p>${e(t('approvalDescription'))}</p></div>${badge('enabled')}</div><div class="security-line"><div><h3>${e(t('dryRun'))}</h3><p>${e(t('dryRunDescription'))}</p></div>${badge('enabled')}</div><div class="security-line"><div><h3>${e(t('killSwitch'))}</h3><p>${e(t('killDescription'))}</p></div>${button(state.policies.kill_switch?'disableKill':'enableKill','kill-switch',{class:state.policies.kill_switch?'small':'small danger',disabled:!allowed('admin')})}</div><div class="security-line"><div><h3>${e(t('manualLearning'))}</h3><p>${e(t('manualLearningText'))}</p></div>${badge('enabled')}</div></div>`)}</div><div class="section-gap">${panel('bankReadiness',`<div class="panel-body"><p class="small-text muted">${e(t('readinessIntro'))}</p><div class="readiness-list">${['readinessIdentity','readinessData','readinessInfra','readinessActions','readinessAudit','readinessSecurity'].map(k=>`<div class="readiness-item">${icon('alert')}<span>${e(t(k))}</span></div>`).join('')}</div></div>`)}</div>`;}
const pages={overview,incidents,events,learning,dataset,responses,audit,sources,judge,settings,lab};

async function loadLab(){const seq=++labRequestSeq;try{const data=await api('/api/lab/state');if(seq!==labRequestSeq||route!=='lab')return;labData=data;document.querySelector('#page').innerHTML=lab();}catch(err){toast(errorText(err),true);}}
function lab(){
 if(!labData)return `<div class="empty">${e(t('loading'))}</div>`;
 if(!labData.enabled)return `<div class="callout warning">${e(t('labDisabled'))}</div>`;
 const l=labData, m=l.models.find(x=>x.status==='active'), report=m?.report, last=l.runs[0];
 const comparison=report?`<div class="table-wrap"><table><thead><tr><th>${e(t('model'))}</th><th>${e(t('precision'))}</th><th>${e(t('recall'))}</th><th>${e(t('fpr'))}</th><th>TP / FP / FN</th></tr></thead><tbody>${[['labRules',report.rules],['labML',report.candidate],['labHybrid',report.hybrid]].map(([name,v])=>`<tr><td>${e(t(name))}</td><td>${pct(v.precision)}</td><td>${pct(v.recall)}</td><td>${pct(v.fpr)}</td><td>${v.tp} / ${v.fp} / ${v.fn}</td></tr>`).join('')}</tbody></table></div><div class="panel-body"><p>${e(t('labAdded'))}: <strong>${n(report.model_only_true_positives)}</strong> · ${e(t('labAddedFP'))}: <strong>${n(report.model_only_false_positives)}</strong></p><p class="tiny muted section-gap">${e(t('labDatasetNote'))}</p><p class="mono tiny section-gap">${e(m.version)} · ${e(m.artifact_hash.slice(0,16))}</p><details><summary>${e(t('manifest'))}</summary>${raw({report,source:m.dataset_manifest})}</details></div>`:`<div class="panel-body callout warning">${e(t('labModelMissing'))}</div>`;
 const results=last?.results?`<div class="panel-body"><p>${e(t('labAttackCount'))}: ${last.summary.attacks} · ${e(t('labBlocked'))}: ${last.summary.blocked} · ${e(t('labEscalated'))}: ${last.summary.escalated} · ${e(t('labMissed'))}: ${last.summary.missed} · ${e(t('labBenignBlocked'))}: ${last.summary.benign_blocked}/${last.summary.benign}</p><p class="tiny muted section-gap">${last.summary.actual_tcp_requests} TCP · ${e(t('labScenarioNote'))}</p></div><div class="table-wrap"><table><thead><tr><th>${e(t('scenario'))}</th><th>${e(t('labControl'))}</th><th>${e(t('labProtection'))}</th><th>AI</th><th>${e(t('labDecisionSource'))}</th></tr></thead><tbody>${last.results.map(r=>`<tr><td>${e(r.scenario)}</td><td>${r.control?`HTTP ${r.control.http_status}${r.control.rows_returned!==undefined?` · ${r.control.rows_returned} ${e(t('labRows'))}`:''}`:'—'}</td><td>HTTP ${r.protected.http_status} · ${e(t(r.protected.blocked?'labBlocked':r.protected.incident_id?'labEscalated':'labAllowed'))}<span class="cell-sub">${e(t('labTargetExecuted'))}: ${e(t(r.protected.target_executed?'yes':'no'))}</span></td><td>${pct(r.protected.model_score)}</td><td>${e(r.protected.blocked_by||'—')}<span class="cell-sub">${r.protected.latency_ms} ms</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${e(t('labRunHint'))}</div>`;
 return `<div class="callout"><strong>${e(t('labFlow'))}</strong><p>${e(t('labBoundary'))}${l.storage==='ephemeral'?e({uz:' Vercel demo: ma’lumotlar vaqtinchalik. Datasetni eksport qiling; doimiy saqlash lokal versiyada.',ru:' Демо Vercel: данные временные. Экспортируйте датасет; постоянное хранение в локальной версии.',en:' Vercel demo: temporary shared storage. Export the dataset; use the local version for durable storage.'}[locale]):''}</p></div><div class="button-row section-gap">${button('labRun','lab-run',{class:'primary',icon:'play',disabled:!allowed('analyst','admin')})}${button('labCustom','lab-custom',{icon:'activity',disabled:!allowed('analyst','admin')})}${button('labTrain','lab-train',{icon:'brain',disabled:!canTrain()})}${button('exportDataset','lab-export',{icon:'download',disabled:!canExport()})}${button(l.policy.auto_block?'labObserve':'labProtect','lab-policy',{disabled:!allowed('admin')})}</div><p class="tiny muted section-gap">${e(t(l.policy.auto_block?'labPolicyProtect':'labPolicyObserve'))}</p>${stats([['labTraffic',l.events_total,'labRealTCP','activity'],['labBlocked',l.blocked,'labInlineBlock','shield'],['labEscalated',l.escalated,'labSOCInbox','users'],['labFeedback',l.feedback_rows,'independentReview','database']])}${labLastRequest?panel('labLastRequest',`<div class="panel-body">${raw(labLastRequest)}</div>`):''}<div class="grid two section-gap">${panel('labAIComparison',comparison)}${panel('labFeedbackFlow',`<div class="panel-body"><p>${e(t('labFeedbackHint'))}</p>${metricRows([['labFeedback',n(l.feedback_rows)],['pendingReview',n(l.pending_labels)],['activeModel',l.model_version||'—']])}<p class="tiny muted section-gap">${e(t('labFeedbackScope'))}</p><details><summary>Dataset SHA-256</summary><code>${e(l.dataset_hash)}</code></details><div class="button-row section-gap">${button('incidents','go-incidents',{class:'small'})}${button('labDataset','lab-dataset',{class:'small'})}</div></div>`)}</div><div class="section-gap">${panel('labLastRun',results)}</div><div class="section-gap">${panel('labSOCInbox',labEventTable(l.events))}</div><div class="grid two section-gap">${panel('labelsQueue',l.labels.length?l.labels.map(x=>`<article class="review-card"><div class="model-header"><code>${e(x.event_id)}</code>${badge(x.status)}</div><p>${e(t(x.label))} · ${e(t('labDisposition'))}: ${e(t('labAction_'+x.disposition))}</p><p class="review-reason">${e(x.reason)}</p><p class="tiny muted">${e(x.created_by)} → ${e(x.reviewed_by||'—')}</p><div class="button-row section-gap">${x.status==='pending'?button('approve','label-approve',{id:x.id,class:'small primary',disabled:!canReview()||x.created_by===auth.user.username||x.label==='uncertain'})+button('reject','label-reject',{id:x.id,class:'small',disabled:!canReview()||x.created_by===auth.user.username}):''}</div></article>`).join(''):empty())}${panel('models',l.models.map(x=>`<article class="model-card"><div class="model-header"><h3>${e(x.version)}</h3>${badge(x.status)}</div><p class="tiny muted">${e(x.trained_by)} · ${e(t('labFeedback'))}: ${n(x.report.feedback?.train)} ${e(t('trainSplit'))}</p>${x.data_review_required?`<p class="callout warning">${e(errorText('TRAINING_LABELS_CHANGED'))}</p>`:''}<details><summary>${e(t('details'))}</summary>${raw(x.report)}</details><div class="button-row section-gap">${x.status==='challenger'?button('promote','lab-promote',{id:x.id,class:'small primary',disabled:!canReview()||x.trained_by===auth.user.username||!x.report.eligible||x.data_review_required}):''}${x.status==='retired'?button('rollback','lab-rollback',{id:x.id,class:'small',disabled:!allowed('admin')||x.data_review_required||!x.compatible}):''}</div></article>`).join(''))}</div>${l.actions.length?`<div class="section-gap">${panel('labActions',`<div class="panel-body">${l.actions.map(a=>`<div class="metric-row"><span>${e(t('labAction_'+a.kind))} · ${e(a.actor)}<br><code>${e(a.id)}</code></span><strong>${e(a.status)} · ${e(t(a.effective?'yes':'no'))}</strong></div>`).join('')}</div>`)}</div>`:''}`;
}
function labEventTable(rows){return `<div class="table-wrap"><table><thead><tr><th>${e(t('time'))}</th><th>${e(t('eventType'))}</th><th>AI / ${e(t('labRules'))}</th><th>${e(t('labProtection'))}</th><th>${e(t('decisions'))}</th></tr></thead><tbody>${rows.slice(0,40).map(x=>`<tr><td>${date(x.event_time,true)}<span class="cell-sub">${e(x.mode)}</span></td><td>${e(x.method)} ${e(x.route)}<span class="cell-sub mono">${e(x.id)}</span></td><td>${pct(x.model_score)} / ${e(t(x.rule_alert?'yes':'no'))}</td><td>${e(t(x.blocked?'labBlocked':x.alert?'labEscalated':'labAllowed'))}<span class="cell-sub">HTTP ${x.response_status} · ${e(x.blocked_by||'—')}</span></td><td>${button('labReview','lab-feedback',{id:x.id,class:'small',disabled:!canWrite()})}</td></tr>`).join('')}</tbody></table></div>`;}

function showDialog(title,html,{small=false,submit=false,submitKey='confirm',callback=null}={}){dialog.className=small?'dialog-small':'';dialog.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">AI-SOC / ${e(t('detail'))}</span><h2 id="dialog-title">${e(title)}</h2></div><button class="icon-button ghost" data-cmd="dialog-close" aria-label="${e(t('close'))}">${icon('close')}</button></div>${submit?'<form id="dialog-form">':''}<div class="dialog-content">${html}<div id="dialog-error" role="alert"></div></div><div class="dialog-footer">${button(submit?'cancel':'close','dialog-close')}${submit?`<button class="primary" type="submit">${e(t(submitKey))}</button>`:''}</div>${submit?'</form>':''}`;dialogCallback=callback;if(!dialog.open)dialog.showModal();}
function confirmMutation(title,text,path,body={},withReason=true){showDialog(t(title),`<p class="small-text muted">${e(t(text))}</p><div class="section-gap">${withReason?reasonField():''}</div>`,{small:true,submit:true,callback:async(fd)=>mutate(path,{...body,...(withReason?{reason:fd.get('reason')}: {})})});}
async function showIncident(id){currentDetail=await api('/api/incidents/'+encodeURIComponent(id));detailTab='evidence';renderIncident();}
function renderIncident(){const {incident:i,events:ev,labels,actions}=currentDetail;let body='';if(detailTab==='evidence')body=`<div class="reason-list">${i.reason_codes.map(code=>`<div class="reason-item">${icon('info')}<div>${e(t(code))}<small class="mono">${e(code)}</small></div></div>`).join('')}</div><div class="button-row">${i.mitre.map(code=>`<a class="badge" target="_blank" rel="noopener noreferrer" href="https://attack.mitre.org/techniques/${e(code.replace('.','/'))}/">${e(code)} ↗</a>`).join('')}</div><h3 class="section-gap">${e(t('eventTimeline'))}</h3><div class="section-gap">${ev.map(x=>`<div class="evidence-row"><time>${date(x.event_time)} UTC</time><h3>${e(t(x.event_type))} · ${e(t(x.source))}</h3><p>${e(x.asset_id)} · ${e(x.src_ip)} → ${e(x.dst_ip)} · ${n(x.bytes_out)} B</p><div class="evidence-meta"><code>${e(x.id)}</code><code>${e(t('riskScore'))}: ${x.score}</code></div></div>`).join('')}</div>`;
else if(detailTab==='analysis')body=`<p class="muted small-text">${e(t('riskNote'))}</p><div class="table-wrap section-gap"><table><thead><tr><th>${e(t('features'))}</th><th>${e(t('featureValue'))}</th></tr></thead><tbody>${Object.entries(i.features||{}).map(([k,v])=>`<tr><td class="mono">${e(k)}</td><td>${Number(v).toFixed(3)}</td></tr>`).join('')}</tbody></table></div><details><summary>${e(t('rawRecord'))}</summary>${raw(i)}</details>`;
else if(detailTab==='decisions')body=`<p class="muted small-text">${e(t('labelHint'))}</p><div class="button-row section-gap">${button('submitLabel','submit-label',{id:i.id,class:'primary',disabled:!canWrite()})}${button('updateStatus','incident-status',{id:i.id,disabled:!canWrite()})}</div><div class="section-gap">${labels.map(labelCard).join('')||`<p class="muted">${e(t('noLabels'))}</p>`}</div>`;
else if(i.detector==='http')body=`<p class="muted small-text">${e(t('labFeedbackHint'))}</p><div class="button-row section-gap">${button('lab','go-lab',{class:'primary'})}</div>`;
else body=`<p class="muted small-text">${e(t('planHint'))}</p><div class="button-row section-gap">${button('requestAction','request-action',{id:i.id,class:'primary',disabled:!allowed('analyst','admin')})}</div><div class="section-gap">${actions.map(actionCard).join('')||`<p class="muted">${e(t('noActions'))}</p>`}</div>`;
showDialog(t(i.title_code),`<div class="detail-summary"><div><small>${e(t('severity'))}</small>${badge(i.severity)}</div><div><small>${e(t('riskScore'))}</small>${score(i.score)}</div><div><small>${e(t('asset'))}</small><strong>${e(i.asset_id)}</strong></div><div><small>${e(t('status'))}</small>${badge(i.status)}</div></div><p class="tiny muted mono">${e(i.id)} · ${e(i.model_version)}</p><div class="detail-tabs section-gap" role="tablist">${['evidence','analysis','decisions','response'].map(key=>`<button type="button" role="tab" aria-selected="${key===detailTab}" class="${key===detailTab?'active':''}" data-cmd="detail-tab" data-id="${key}">${e(t(key))}</button>`).join('')}</div><div class="tab-panel" role="tabpanel">${body}</div>`);}
async function exportData(kind){const res=await fetch('/api/export/'+kind,{credentials:'same-origin'});if(!res.ok)throw Error((await res.json()).detail);const blob=await res.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`ai-soc-${kind}-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('downloadReady'));await refresh();}

async function command(cmd,id){
 if(cmd==='lab-run'){await api('/api/lab/run',{});await refresh();return;}
 if(cmd==='lab-custom'){showDialog(t('labCustom'),`<p class="tiny muted">${e(t('labBoundary'))}${l.storage==='ephemeral'?e({uz:' Vercel demo: ma’lumotlar vaqtinchalik. Datasetni eksport qiling; doimiy saqlash lokal versiyada.',ru:' Демо Vercel: данные временные. Экспортируйте датасет; постоянное хранение в локальной версии.',en:' Vercel demo: temporary shared storage. Export the dataset; use the local version for durable storage.'}[locale]):''}</p><div class="field section-gap"><label for="lab-path">${e(t('labPath'))}</label><select id="lab-path" name="path"><option>/search</option><option>/echo</option><option>/file</option><option>/login</option></select></div><div class="field"><label for="lab-payload">${e(t('labPayload'))}</label><textarea id="lab-payload" name="payload" maxlength="3500" required>books</textarea></div><div class="field"><label for="lab-method">HTTP</label><select id="lab-method" name="method"><option>GET</option><option>POST</option></select></div>`,{submit:true,callback:async fd=>{labLastRequest=await api('/api/lab/request',{path:fd.get('path'),payload:fd.get('payload'),method:fd.get('method')});await refresh();}});return;}
 if(cmd==='lab-feedback'){const item=labData.events.find(x=>x.id===id);showDialog(t('labReview'),`<p class="mono tiny">${e(id)} · ${e(item.model_version)}</p><details><summary>${e(t('evidence'))}</summary>${raw(item)}</details><div class="field section-gap"><label for="label">${e(t('label'))}</label><select id="label" name="label">${['malicious','benign','uncertain'].map(k=>`<option value="${k}">${e(t(k))}</option>`).join('')}</select></div><div class="field"><label for="disposition">${e(t('labDisposition'))}</label><select id="disposition" name="disposition">${['monitor','block','release','escalate'].map(k=>`<option value="${k}">${e(t('labAction_'+k))}</option>`).join('')}</select></div>${reasonField()}<p class="tiny muted">${e(t('labFeedbackScope'))}</p>`,{submit:true,callback:fd=>mutate(`/api/lab/events/${id}/feedback`,{label:fd.get('label'),disposition:fd.get('disposition'),reason:fd.get('reason')})});return;}
 if(cmd==='lab-policy'){await mutate('/api/lab/policy',{auto_block:!labData.policy.auto_block});return;}
 if(cmd==='lab-train'){const hash=labData.dataset_hash;showDialog(t('labTrain'),`<p>${e(t('labFeedbackHint'))}</p><p class="mono tiny section-gap">${e(hash)}</p><label class="review-ack section-gap"><input type="checkbox" required> <span>${e(t('reviewAcknowledgment'))}</span></label>`,{submit:true,callback:()=>mutate('/api/lab/train',{dataset_hash:hash,reviewed:true})});return;}
 if(cmd==='lab-promote'||cmd==='lab-rollback'){confirmMutation(cmd==='lab-promote'?'promote':'rollback','labFeedbackScope',`/api/lab/models/${id}/${cmd==='lab-promote'?'promote':'rollback'}`);return;}
 if(cmd==='lab-dataset'){const data=await api('/api/lab/dataset');showDialog(t('labDataset'),raw(data));return;}
 if(cmd==='lab-export'){const response=await fetch('/api/lab/export',{credentials:'same-origin'});if(!response.ok)throw Error((await response.json()).detail);const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='ai-soc-http-feedback.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(cmd.startsWith('go-')){dialog.close();navigate(cmd.slice(3));return;}
 if(cmd==='dialog-close'){dialog.close();return;}
 if(cmd==='menu'||cmd==='menu-close'){document.querySelector('.sidebar')?.classList.toggle('open',cmd==='menu');document.querySelector('.overlay')?.classList.toggle('open',cmd==='menu');return;}
 if(cmd==='demo-login'){auth=await api('/api/auth/demo',{role:id});await refresh();return;}
 if(cmd==='logout'){await api('/api/auth/logout',{});auth=null;state=null;dialog.close();renderLogin();return;}
 if(cmd==='refresh'){await refresh();return;}
 if(cmd==='incident'){await showIncident(id);return;}
 if(cmd==='detail-tab'){detailTab=id;renderIncident();return;}
 if(cmd==='event'){const item=eventData?.items.find(x=>x.id===id)||state.events.find(x=>x.id===id);showDialog(t('rawRecord'),raw(item));return;}
 if(cmd==='audit-row'){showDialog(t('auditRecord'),raw(state.audit.find(x=>x.id===id)));return;}
 if(cmd==='dataset-row'){showDialog(t('trainingData'),raw(datasetData?.items.find(x=>x.event_id===id)));return;}
 if(cmd==='event-next'||cmd==='event-prev'){eventPage+=cmd.endsWith('next')?1:-1;await loadEvents();return;}
 if(cmd==='dataset-next'||cmd==='dataset-prev'){datasetPage+=cmd.endsWith('next')?1:-1;await loadDataset();return;}
 if(cmd==='replay'){showDialog(t('replayTitle'),`<p class="small-text muted">${e(t('replayHint'))}</p><div class="field section-gap"><label for="scenario">${e(t('scenario'))}</label><select name="scenario" id="scenario">${['credential_compromise','exfiltration','benign','mixed'].map(s=>`<option value="${s}">${e(t(s))}</option>`).join('')}</select></div>`,{small:true,submit:true,submitKey:'replay',callback:fd=>mutate('/api/demo/replay',{scenario:fd.get('scenario')})});return;}
 if(cmd==='submit-label'){showDialog(t('submitLabel'),`<p class="small-text muted">${e(t('labelHint'))}</p><div class="field section-gap"><label for="label">${e(t('label'))}</label><select id="label" name="label">${['malicious','benign','uncertain'].map(s=>`<option value="${s}">${e(t(s))}</option>`).join('')}</select></div>${reasonField()}`,{small:true,submit:true,callback:fd=>mutate(`/api/incidents/${id}/labels`,{label:fd.get('label'),reason:fd.get('reason')})});return;}
 if(cmd==='incident-status'){const i=state.incidents.find(x=>x.id===id);showDialog(t('updateStatus'),`<div class="field"><label for="status">${e(t('status'))}</label><select id="status" name="status">${['open','investigating','contained','closed'].map(s=>`<option value="${s}" ${i.status===s?'selected':''}>${e(t(s))}</option>`).join('')}</select></div><div class="field"><label for="owner">${e(t('owner'))}</label><input name="owner" id="owner" value="${e(i.owner||auth.user.username)}" maxlength="80" required pattern="[A-Za-z0-9_.@-]+"></div>`,{small:true,submit:true,callback:fd=>mutate(`/api/incidents/${id}/status`,{status:fd.get('status'),owner:fd.get('owner')})});return;}
 if(cmd==='request-action'){showDialog(t('requestAction'),`<p class="small-text muted">${e(t('planHint'))}</p><div class="field section-gap"><label for="kind">${e(t('actionKind'))}</label><select id="kind" name="kind">${['isolate_endpoint','revoke_sessions','block_destination'].map(k=>`<option value="${k}">${e(t(k))}</option>`).join('')}</select></div>${reasonField()}`,{small:true,submit:true,callback:fd=>mutate(`/api/incidents/${id}/actions`,{kind:fd.get('kind'),reason:fd.get('reason')})});return;}
 if(cmd==='label-approve'||cmd==='label-reject'){confirmMutation(cmd==='label-approve'?'approveLabel':'rejectLabel','reviewLabelHint',`/api/labels/${id}/review`,{decision:cmd==='label-approve'?'approve':'reject'});return;}
 if(cmd.startsWith('action-')){const operation=cmd.slice(7);confirmMutation(operation,'actionConfirm',`/api/actions/${id}/${operation}`,{},!['execute','verify'].includes(operation));return;}
 if(cmd==='train'){const fingerprint=state.learning.dataset_hash;showDialog(t('train'),`<div class="callout"><strong>${e(t('manualLearning'))}</strong><p>${e(t('manualLearningText'))}</p></div>${metricRows([['trainingData',n(state.learning.dataset_count)],['positive',n(state.learning.readiness.positive)],['negative',n(state.learning.readiness.negative)]])}<p class="tiny muted section-gap">${e(t('metricsSynthetic'))}</p><p class="mono tiny section-gap" style="overflow-wrap:anywhere">SHA-256: ${e(fingerprint)}</p><label class="review-ack section-gap"><input type="checkbox" name="reviewed" required> <span>${e(t('reviewAcknowledgment'))}</span></label>`,{small:true,submit:true,submitKey:'train',callback:()=>mutate('/api/learning/train',{dataset_hash:fingerprint,reviewed:true})});return;}
 if(cmd==='promote'){confirmMutation('promote','promoteConfirm',`/api/models/${id}/promote`);return;}
 if(cmd==='model-rollback'){confirmMutation('rollback','rollbackConfirm',`/api/models/${id}/rollback`);return;}
 if(cmd==='kill-switch'){confirmMutation('killSwitch','killDescription','/api/policies',{kill_switch:!state.policies.kill_switch},false);return;}
 if(cmd==='verify-chain'){const r=await api('/api/audit/verify');document.querySelector('#audit-verification').innerHTML=`<div class="callout ${r.valid?'':'warning'}"><strong>${e(t(r.valid?'chainValid':'chainInvalid'))}</strong><p>${n(r.checked)} ${e(t('checked'))}</p><p class="mono tiny" style="overflow-wrap:anywhere">${e(r.head)}</p><p>${e(t('chainHint'))}</p></div>`;return;}
 if(cmd==='export-dataset'||cmd==='export-evidence'){await exportData(cmd.slice(7));return;}
}

document.addEventListener('click',async event=>{const target=event.target.closest('[data-cmd]');if(!target||target.disabled)return;target.disabled=true;try{await command(target.dataset.cmd,target.dataset.id);}catch(err){toast(errorText(err),true);}finally{if(target.isConnected)target.disabled=false;}});
document.addEventListener('change',event=>{const target=event.target;if(target.matches('[data-locale]')){locale=target.value;localStorage.setItem('soc.locale',locale);dialog.close();auth?renderApp():renderLogin();}else if(target.matches('select[data-filter]')){pageFilter[target.dataset.filter]=target.value;if(route==='incidents')document.querySelector('#incident-results').innerHTML=incidentTable(filteredIncidents());else{eventPage=0;loadEvents();}}});
let debounce;
document.addEventListener('input',event=>{const target=event.target;if(target.matches('[data-filter="q"]')){pageFilter.q=target.value;if(route==='incidents')document.querySelector('#incident-results').innerHTML=incidentTable(filteredIncidents());else if(route==='events'){++eventRequestSeq;clearTimeout(debounce);debounce=setTimeout(()=>{if(route==='events'&&location.hash.slice(1)==='events'&&target.isConnected){eventPage=0;loadEvents();}},250);}}if(target.matches('[data-audit-filter]')){auditFilter=target.value;document.querySelector('#audit-results').innerHTML=auditTable(filteredAudit());}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,fd=new FormData(form);if(form.id==='global-search'){pageFilter.q=fd.get('q');if(route==='incidents')renderApp();else navigate('incidents');return;}const submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=true;try{if(form.id==='login-form'){auth=await api('/api/auth/login',{username:fd.get('username'),password:fd.get('password')});await refresh();}else if(form.id==='dialog-form'&&dialogCallback){await dialogCallback(fd);dialog.close();}}catch(err){if(form.id==='login-form')renderLogin(errorText(err));else{const el=document.querySelector('#dialog-error');if(el)el.innerHTML=`<div class="error-box section-gap">${e(errorText(err))}</div>`;else toast(errorText(err),true);}}finally{if(submit?.isConnected)submit.disabled=false;}});
window.addEventListener('hashchange',()=>{clearTimeout(debounce);++eventRequestSeq;if(auth){pageFilter={q:pageFilter.q,severity:'',status:'',source:''};eventPage=0;renderApp();window.scrollTo(0,0);document.querySelector('#main')?.focus({preventScroll:true});}});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!dialog.open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){event.preventDefault();document.querySelector('#global-search input')?.focus();}});
setInterval(()=>{if(canAutoRefresh())refresh(true,true);},5000);
try{auth=await api('/api/auth/me');await refresh();}catch{renderLogin();}
